package com.rustypayments.legacy;

import com.rustypayments.PaymentCalendar;
import java.time.DayOfWeek;
import java.time.LocalDate;
import java.time.LocalTime;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import java.time.temporal.ChronoUnit;

/**
 * Modernized implementation of the PaymentCalendar.
 */
public class LegacyPaymentCalendar implements PaymentCalendar {

    private static final ZoneId BANK_ZONE = ZoneId.of("Europe/Warsaw");
    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("uuuu-MM-dd")
            .withResolverStyle(ResolverStyle.STRICT);
    private static final LocalTime CUTOFF = LocalTime.of(16, 0, 0);

    @Override
    public boolean isBusinessDay(String date) {
        return isBusinessDay(parseLocalDate(date));
    }

    @Override
    public String processingDate(String submittedAt) {
        ZonedDateTime submitted = parseInstant(submittedAt);
        LocalDate date = submitted.toLocalDate();
        LocalTime time = submitted.toLocalTime();

        if (isBusinessDay(date) && !time.isAfter(CUTOFF)) {
            return date.toString();
        }
        return nextBusinessDay(date).toString();
    }

    @Override
    public String settlementDate(String submittedAt) {
        LocalDate processing = parseLocalDate(processingDate(submittedAt));
        return nextBusinessDay(processing).toString();
    }

    @Override
    public int daysLate(String dueDate, String paidAt) {
        LocalDate due = parseLocalDate(dueDate);
        LocalDate paid = parseInstant(paidAt).toLocalDate();
        return (int) Math.max(0, ChronoUnit.DAYS.between(due, paid));
    }

    @Override
    public String addMonths(String date, int months) {
        LocalDate start = parseLocalDate(date);
        boolean wasMonthEnd = (start.getDayOfMonth() == start.lengthOfMonth());
        LocalDate result = start.plusMonths(months);
        if (wasMonthEnd) {
            result = result.withDayOfMonth(result.lengthOfMonth());
        }
        return result.toString();
    }

    private LocalDate parseLocalDate(String dateStr) {
        if (dateStr == null) throw new IllegalArgumentException("Date is null");
        try {
            return LocalDate.parse(dateStr, DATE_FORMAT);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("Invalid date format: " + dateStr);
        }
    }

    private ZonedDateTime parseInstant(String instantStr) {
        if (instantStr == null) throw new IllegalArgumentException("Instant is null");
        try {
            return ZonedDateTime.parse(instantStr, DateTimeFormatter.ISO_OFFSET_DATE_TIME)
                    .withZoneSameInstant(BANK_ZONE);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("Invalid instant format: " + instantStr);
        }
    }

    private boolean isBusinessDay(LocalDate date) {
        DayOfWeek dow = date.getDayOfWeek();
        if (dow == DayOfWeek.SATURDAY || dow == DayOfWeek.SUNDAY) {
            return false;
        }
        int m = date.getMonthValue();
        int d = date.getDayOfMonth();
        if (m == 1 && (d == 1 || d == 6)) return false;
        if (m == 5 && (d == 1 || d == 3)) return false;
        if (m == 8 && d == 15) return false;
        if (m == 11 && (d == 1 || d == 11)) return false;
        if (m == 12 && (d == 25 || d == 26)) return false;
        return true;
    }

    private LocalDate nextBusinessDay(LocalDate date) {
        LocalDate next = date.plusDays(1);
        while (!isBusinessDay(next)) {
            next = next.plusDays(1);
        }
        return next;
    }
}

